// build-signer-pages-bundle.mjs
// Generates a single self-contained Pages Advanced-Mode worker (`deploy/signer/_worker.js`)
// from worker/cf-signer-core.mjs + worker/cf-signer-worker.mjs by stripping the internal
// core import and concatenating (same Workers runtime; Pages needs one file named _worker.js).
//
// Usage: node scripts/build-signer-pages-bundle.mjs
// Then deploy with wrangler (see worker/README.md "Cloudflare thin signer").
import { readFileSync, mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

const corePath = join(root, 'worker', 'cf-signer-core.mjs');
const workerPath = join(root, 'worker', 'cf-signer-worker.mjs');

const core = readFileSync(corePath, 'utf8');
const worker = readFileSync(workerPath, 'utf8');

const importRe = /import\s*\{[^}]*\}\s*from\s*['"]\.\/cf-signer-core\.mjs['"];\s*/;
if (!importRe.test(worker)) {
  throw new Error(
    'worker/cf-signer-worker.mjs no longer imports ./cf-signer-core.mjs ' +
    '— update this bundle script before shipping.',
  );
}

const bundle = [
  '// vibecatch-cf-signer — single-file Pages Advanced-Mode worker.',
  '// GENERATED by scripts/build-signer-pages-bundle.mjs — do not edit directly.',
  '// Edit worker/cf-signer-core.mjs + worker/cf-signer-worker.mjs, then rebuild.',
  '',
  core.replace(/\n$/, ''),
  '',
  worker.replace(importRe, '').replace(/\n$/, ''),
  '',
].join('\n');

const outDir = join(root, 'deploy', 'signer');
const outFile = join(outDir, '_worker.js');
mkdirSync(outDir, { recursive: true });
writeFileSync(outFile, bundle);

const check = spawnSync(process.execPath, ['--check', outFile], { encoding: 'utf8' });
if (check.status !== 0) {
  throw new Error(`node --check failed on ${outFile}:\n${check.stderr || check.stdout || '(no output)'}`);
}

console.log(`wrote ${outFile} (${Buffer.byteLength(bundle)} bytes, node --check clean)`);